    }

    close(id: string) {
        const entry = this.entries.find((candidate) => candidate.id === id)
        if (!entry) return

        entry.fallbackAnchorElement.remove()
        this.setEntries(this.entries.filter((candidate) => candidate.id !== id))
    }

    closeCardDetailsByInternalId(cardInternalId: string) {
        this.removeEntries((entry) => entry.kind === 'card-details' && entry.cardInternalId === cardInternalId)
    }

    closeCardDetails() {
        this.removeEntries((entry) => entry.kind === 'card-details')
    }

    activate(id: string) {
        const entryIndex = this.entries.findIndex((entry) => entry.id === id)
        if (entryIndex < 0 || entryIndex === this.entries.length - 1) return

        const entry = this.entries[entryIndex]
        this.setEntries([...this.entries.filter((candidate) => candidate.id !== id), entry])
    }

    clear() {
        this.removeEntries(() => true)
    }

    private readonly handleDataServiceChanged = () => {
        const nextProjectKey = projectKey(this.dataService)
        if (nextProjectKey === this.currentProjectKey) return

        this.currentProjectKey = nextProjectKey
        this.clear()
    }

    private findCardDetails(cardInternalId: string) {
        return this.entries.find((entry): entry is CardDetailsPopupEntry => (
            entry.kind === 'card-details' && entry.cardInternalId === cardInternalId
        ))
    }

    private openCardDetails(
        cardInternalId: string,
        anchorElement: HTMLElement,
        diffSelection: CardDetailsDiffSelection | null,
    ) {
        const entry: CardDetailsPopupEntry = {
            anchorElement,
            cardInternalId,
            diffSelection,
            fallbackAnchorElement: createFallbackAnchor(anchorElement),
            id: `card-details-popup-${this.nextId}`,
            kind: 'card-details',
        }
        this.nextId += 1
        this.setEntries([...this.entries, entry])
    }

    private removeEntries(shouldRemove: (entry: CardPopupEntry) => boolean) {
        const removedEntries = this.entries.filter(shouldRemove)
        if (removedEntries.length === 0) return

        removedEntries.forEach(({ fallbackAnchorElement }) => fallbackAnchorElement.remove())
        this.setEntries(this.entries.filter((entry) => !shouldRemove(entry)))
    }

    private replaceEntry(replacement: CardPopupEntry) {
        this.setEntries(this.entries.map((entry) => entry.id === replacement.id ? replacement : entry))
    }

    private requireCardDetails(id: string) {
        const entry = this.entries.find((candidate): candidate is CardDetailsPopupEntry => (
            candidate.id === id && candidate.kind === 'card-details'
        ))
        if (!entry) throw new Error(`Card details popup does not exist: ${id}`)

        return entry
    }

    private setEntries(entries: CardPopupEntry[]) {
        this.entries = entries
        this.dispatchEvent(new Event(CARD_POPUPS_CHANGED_EVENT))
    }
}

export const cardPopupService = register('cardPopupService', new CardPopupService(dataService))

export function subscribeCardPopups(onStoreChange: () => void) {
    cardPopupService.addEventListener(CARD_POPUPS_CHANGED_EVENT, onStoreChange)

    return () => cardPopupService.removeEventListener(CARD_POPUPS_CHANGED_EVENT, onStoreChange)
}

import { Box, Chip, IconButton, Paper, Tooltip, Typography } from '@mui/material'
import { SortableContext, verticalListSortingStrategy } from '@dnd-kit/sortable'
import Plus from 'mdi-material-ui/Plus'
import { useCallback, useSyncExternalStore } from 'react'
import type { ReactNode } from 'react'
import type { CardTypeConfig } from '../../data/data_types'
import { requestOpenNewCardDialog } from '../project_command_events'
import { CardColumnEndDropTarget } from './card_column_end_drop_target'
import { cardDragDropService } from './card_drag_drop_service'
import { CardView, type CardHandlers } from './project_card_view'
import type { VisibleCardColumn } from './use_card_view_columns'
import { useCardColumnCards } from './use_card_column_cards'
import { useProjectReadOnly } from '../hooks/use_project_read_only'

const MIN_COLUMN_WIDTH = 200
const MAX_COLUMN_WIDTH = 320

interface CardColumnProps extends CardHandlers {
    cardTypes: CardTypeConfig[]
    column: VisibleCardColumn
    isMobile: boolean
}

/** One status column: a polished droppable stack with header metadata and an empty target. */
export function CardColumn(props: CardColumnProps) {
    const {
        cardTypes, column, isMobile,
        ...handlers
    } = props
    const cardPaths = useCardColumnCards(column.status)
    const readOnly = useProjectReadOnly()
    const subscribe = useCallback(
        (listener: () => void) => cardDragDropService.subscribeColumn(column.status, listener),
        [column.status],
    )
    const getSnapshot = useCallback(
        () => cardDragDropService.getColumnPreview(column.status),
        [column.status],
    )
    const dropPreview = useSyncExternalStore(subscribe, getSnapshot, getSnapshot)
    const dropPreviewHeight = dropPreview?.dropPreviewHeight ?? null
    const dropPreviewIndex = dropPreview?.dropPreviewIndex ?? null
    const columnLabel = column.status || 'Unassigned'
    const handleAddCard = () => {
        requestOpenNewCardDialog(column.status)
    }
    const dropPlaceholder = (
        <Box
            aria-label="Card drop position"
            key="drop-preview"
            sx={{
                bgcolor: 'action.selected',
                border: '1.5px dashed',
                borderColor: 'primary.main',
                borderRadius: 1.25,
                minHeight: dropPreviewHeight ?? 107,
            }}
        />
    )
    const cardElements: ReactNode[] = []
    for (let index = 0; index <= cardPaths.length; index += 1) {
        if (dropPreviewIndex === index) cardElements.push(dropPlaceholder)
        const cardPath = cardPaths[index]
        if (!cardPath) continue

        cardElements.push(
            <CardView
                key={cardPath}
                cardPath={cardPath}
                cardTypes={cardTypes}
                isMobile={isMobile}
                {...handlers}
            />,
        )
    }

    return (
        <Paper
            aria-label={`${columnLabel} column`}
            sx={{
                bgcolor: 'action.hover',
                borderRadius: 1.5,
                display: 'flex',
                flex: isMobile ? '0 0 auto' : 1,
                flexDirection: 'column',
                gap: 1,
                maxWidth: isMobile ? '100%' : MAX_COLUMN_WIDTH,
                minWidth: isMobile ? '100%' : MIN_COLUMN_WIDTH,
                p: 1,
            }}
        >
            <Box sx={{ alignItems: 'center', display: 'flex', gap: 1, minHeight: 34, pl: 1, pr: 0.5 }}>
                <Box sx={{ bgcolor: column.color, borderRadius: '3px', flexShrink: 0, height: 8, width: 8 }} />
                <Typography
                    component="h2"
                    sx={{ color: 'text.secondary', fontSize: 12, fontWeight: 700, letterSpacing: 0.6, textTransform: 'uppercase' }}
                >
                    {columnLabel}
                </Typography>
                <Chip
                    label={cardPaths.length}
                    size="small"
                    sx={{ bgcolor: 'background.paper', border: 1, borderColor: 'divider', fontSize: 11, height: 20 }}
                />
                <Box sx={{ flex: 1 }} />
                <Tooltip title="New card">
                    <IconButton aria-label={`Add card from ${columnLabel} column`} disabled={readOnly} onClick={handleAddCard} size="small" sx={{ height: 26, width: 26 }}>
                        <Plus sx={{ fontSize: 16 }} />
                    </IconButton>
                </Tooltip>
            </Box>
            <SortableContext items={cardPaths} strategy={verticalListSortingStrategy}>
                {cardElements}
                {cardPaths.length === 0 && dropPreviewIndex === null ? (
                    <Box
                        sx={{
                            border: '1.5px dashed',
                            borderColor: 'divider',
                            borderRadius: 1.25,
                            color: 'text.disabled',
                            fontSize: 12,
                            p: 2,
                            textAlign: 'center',
                        }}
                    >
                        Drop a card here
                    </Box>
                ) : null}
                <CardColumnEndDropTarget status={column.status} />
            </SortableContext>
        </Paper>
    )
}

