import { useMediaQuery, useTheme } from '@mui/material'
import { useEffect, useRef, useSyncExternalStore } from 'react'
import { isElectron } from '../../services/electron_lifecycle_bridge'
import { cardPopupService, subscribeCardPopups } from '../../services/card_popup_service'
import { mobileBackDismissService, type MobileBackDismissService } from '../../services/mobile_back_dismiss_service'

const REGISTRATION_ID_PREFIX = 'card-popup-back-dismiss'

function closeTopCardPopup() {
    const topEntry = cardPopupService.getSnapshot().at(-1)
    if (!topEntry) return

    cardPopupService.close(topEntry.id)
}

/**
 * Keeps one back-dismiss registration per open card popup while those popups are full screen,
 * so one back press closes the top popup and repeated presses walk down the stack.
 */
export function useCardPopupBackDismiss(service: MobileBackDismissService = mobileBackDismissService) {
    const theme = useTheme()
    const isMobile = useMediaQuery(theme.breakpoints.down('md'))
    const entries = useSyncExternalStore(
        subscribeCardPopups,
        () => cardPopupService.getSnapshot(),
        () => cardPopupService.getSnapshot(),
    )
    const registeredIdsRef = useRef<string[]>([])
    const nextRegistrationIdRef = useRef(1)
    const serviceRef = useRef(service)
    const isActive = isMobile && !isElectron()
    const requiredRegistrations = isActive ? entries.length : 0

    useEffect(() => {
        serviceRef.current = service
    })

    useEffect(() => {
        const registeredIds = registeredIdsRef.current
        while (registeredIds.length > requiredRegistrations) {
            service.unregister(registeredIds.pop() as string)
        }
        while (registeredIds.length < requiredRegistrations) {
            const registrationId = `${REGISTRATION_ID_PREFIX}-${nextRegistrationIdRef.current}`
            nextRegistrationIdRef.current += 1
            registeredIds.push(registrationId)
            service.register(registrationId, closeTopCardPopup)
        }
    }, [requiredRegistrations, service])

    useEffect(() => () => {
        const registeredIds = registeredIdsRef.current
        while (registeredIds.length > 0) {
            serviceRef.current.unregister(registeredIds.pop() as string)
        }
    }, [])
}

import { register } from './service_injector'

const POPSTATE_EVENT = 'popstate'

interface BackDismissRegistration {
    id: string
    onDismiss: () => void
}

/**
 * Owns browser back-button dismissal for surfaces that are full screen on a small screen.
 *
 * Every registration owns one history entry, so a back press pops the entry of the top registration
 * and asks that surface to dismiss itself. A dismissal is a request: the surface decides whether it
 * actually closes, and the entry is only given back when the surface unregisters.
 */
export class MobileBackDismissService {
    private isListening = false
    private pendingUnwindCount = 0
    private queuedUnwindSteps = 0
    private registrations: BackDismissRegistration[] = []
    private unwindFlushScheduled = false

    getRegistrationCount() {
        return this.registrations.length
    }

    /** Claims one history entry for a surface that is currently full screen on a small screen. */
    register(id: string, onDismiss: () => void) {
        if (!id) throw new Error('Cannot register back dismissal without an ID')
        if (this.registrations.some((registration) => registration.id === id)) {
            throw new Error(`Back dismissal is already registered: ${id}`)
        }

        this.startListening()
        this.registrations = [...this.registrations, { id, onDismiss }]
        window.history.pushState({ md2BackDismiss: id }, '')
    }

    /** Returns the history entry of a surface that has actually closed. */
    unregister(id: string) {
        const remaining = this.registrations.filter((registration) => registration.id !== id)
        if (remaining.length === this.registrations.length) return

        this.registrations = remaining
        this.queueUnwindStep()
    }

    private readonly handlePopState = () => {
        if (this.pendingUnwindCount > 0) {
            this.pendingUnwindCount -= 1
            return
        }

        const topRegistration = this.registrations.at(-1)
        if (!topRegistration) return

        topRegistration.onDismiss()
        window.history.pushState({ md2BackDismiss: topRegistration.id }, '')
    }

    private flushUnwindSteps() {
        this.unwindFlushScheduled = false
        const steps = this.queuedUnwindSteps
        this.queuedUnwindSteps = 0
        if (steps === 0) return

        this.pendingUnwindCount += 1
        window.history.go(-steps)
    }

    private queueUnwindStep() {
        this.queuedUnwindSteps += 1
        if (this.unwindFlushScheduled) return

        this.unwindFlushScheduled = true
        queueMicrotask(() => this.flushUnwindSteps())
    }

    private startListening() {
        if (this.isListening) return

        window.addEventListener(POPSTATE_EVENT, this.handlePopState)
        this.isListening = true
    }
}

export const mobileBackDismissService = register('mobileBackDismissService', new MobileBackDismissService())

import { act, cleanup, render } from '@testing-library/react'
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'
import { cardPopupService } from '../../services/card_popup_service'
import { MobileBackDismissService } from '../../services/mobile_back_dismiss_service'
import { useCardPopupBackDismiss } from './use_card_popup_back_dismiss'

function setScreenWidth(isMobile: boolean) {
    window.matchMedia = ((query: string) => ({
        addEventListener: () => {},
        addListener: () => {},
        dispatchEvent: () => false,
        matches: isMobile,
        media: query,
        onchange: null,
        removeEventListener: () => {},
        removeListener: () => {},
    })) as unknown as typeof window.matchMedia
}

function BackDismissHost({ service }: { service: MobileBackDismissService }) {
    useCardPopupBackDismiss(service)

    return null
}

function openCardDetails(cardInternalId: string) {
    const anchorElement = document.createElement('button')
    document.body.append(anchorElement)
    act(() => cardPopupService.toggleCardDetails(cardInternalId, anchorElement))
}

async function pressBack() {
    await act(async () => {
        window.dispatchEvent(new PopStateEvent('popstate'))
        await Promise.resolve()
    })
}

async function flushPendingUnwinds() {
    await act(async () => {
        await Promise.resolve()
    })
}

describe('useCardPopupBackDismiss', () => {
    beforeEach(() => {
        // A real browser answers history.go with a popstate event, and the service relies on
        // seeing that event to know the move was its own; the stub has to do the same.
        vi.spyOn(window.history, 'go').mockImplementation(() => {
            queueMicrotask(() => window.dispatchEvent(new PopStateEvent('popstate')))
        })
        vi.spyOn(window.history, 'pushState').mockImplementation(() => {})
    })

    afterEach(() => {
        cleanup()
        cardPopupService.clear()
        delete window.md2Lifecycle
        vi.restoreAllMocks()
    })

    it('closes one stacked popup per back press on a small screen in a browser', async () => {
        setScreenWidth(true)
        const service = new MobileBackDismissService()
        render(<BackDismissHost service={service} />)

        openCardDetails('card-one')
        openCardDetails('card-two')

        expect(service.getRegistrationCount()).toBe(2)
        expect(window.history.pushState).toHaveBeenCalledTimes(2)

        await pressBack()

        expect(cardPopupService.getSnapshot().map((entry) => entry.id)).toEqual(['card-details-popup-1'])
        expect(service.getRegistrationCount()).toBe(1)

        await pressBack()

        expect(cardPopupService.getSnapshot()).toEqual([])
        expect(service.getRegistrationCount()).toBe(0)
    })

    it('returns the history entries of popups closed without a back press', async () => {
        setScreenWidth(true)
        const service = new MobileBackDismissService()
        render(<BackDismissHost service={service} />)
        openCardDetails('card-one')
        openCardDetails('card-two')

        act(() => cardPopupService.clear())
        await flushPendingUnwinds()

        expect(service.getRegistrationCount()).toBe(0)
        expect(window.history.go).toHaveBeenCalledExactlyOnceWith(-2)
    })

    it('registers nothing on a wide screen', async () => {
        setScreenWidth(false)
        const service = new MobileBackDismissService()
        render(<BackDismissHost service={service} />)

        openCardDetails('card-one')

        await flushPendingUnwinds()
        expect(service.getRegistrationCount()).toBe(0)
        expect(window.history.pushState).not.toHaveBeenCalled()
    })

    it('registers nothing when the app runs in Electron', async () => {
        setScreenWidth(true)
        window.md2Lifecycle = {
            onFlushRequested: () => () => {},
            reportFlushResult: () => {},
        }
        const service = new MobileBackDismissService()
        render(<BackDismissHost service={service} />)

        openCardDetails('card-one')
        await flushPendingUnwinds()

        expect(service.getRegistrationCount()).toBe(0)
        expect(window.history.pushState).not.toHaveBeenCalled()
    })
})

